func dashboardPage(title, subtitle, body string) string {
	brand := `<div class="brand"><img class="logo" src="/assets/codelocal-icon.png" alt=""><span class="brand-name">CodeLocal</span><span class="brand-tag">CLOUD</span></div>`
	nav := `<div class="nav-label">Control plane</div><nav class="nav" id="dashboard-nav">` +
		`<a href="/dashboard" data-route="/dashboard"><span class="nav-icon">` + navIcons["overview"] + `</span><span>Overview</span></a>` +
		`<a href="/dashboard/workspaces" data-route="/dashboard/workspaces"><span class="nav-icon">` + navIcons["workspaces"] + `</span><span>Workspaces</span></a>` +
		`<a href="/dashboard/devices" data-route="/dashboard/devices"><span class="nav-icon">` + navIcons["devices"] + `</span><span>Devices</span></a>` +
		`<a href="/dashboard/usage" data-route="/dashboard/usage"><span class="nav-icon">` + navIcons["usage"] + `</span><span>Token usage</span></a>` +
		`<a href="/#setup" data-route="/dashboard/connect"><span class="nav-icon">` + navIcons["connect"] + `</span><span>Connect ChatGPT</span></a>` +
		`</nav>`
	status := `<div class="sidebar-spacer"></div><div class="sidebar-status"><div class="sidebar-status-title"><span class="status-dot green"></span>Cloud connected</div><div class="sidebar-status-copy">Local source code and secrets stay on your machine.</div></div><div class="sidebar-foot"><div class="avatar" id="dashboard-avatar">C</div><div class="account"><div class="account-email" id="dashboard-email">CodeLocal</div><div class="account-meta">CodeLocal account</div></div><div id="dashboard-foot-actions"></div></div>`
	script := `<script>(()=>{const path=location.pathname;const labels={'/dashboard':'Overview','/dashboard/workspaces':'Workspaces','/dashboard/devices':'Devices','/dashboard/usage':'Token usage','/dashboard/admin':'Admin'};document.querySelectorAll('[data-route]').forEach(a=>{if(path===a.getAttribute('data-route'))a.classList.add('active')});const heading=document.getElementById('dashboard-title');if(heading&&labels[path])heading.textContent=labels[path];const legacy=[...document.querySelectorAll('.page-body > .actions')].find(el=>el.querySelector('form[action="/logout"]'));if(legacy){const admin=legacy.querySelector('a[href="/dashboard/admin"]');if(admin){const a=document.createElement('a');a.href='/dashboard/admin';a.dataset.route='/dashboard/admin';a.innerHTML='<span class="nav-icon">` + navIcons["admin"] + `</span><span>Admin</span>';document.getElementById('dashboard-nav')?.appendChild(a);if(path==='/dashboard/admin')a.classList.add('active')}const form=legacy.querySelector('form[action="/logout"]');if(form)document.getElementById('dashboard-foot-actions')?.appendChild(form);legacy.remove()}const signed=[...document.querySelectorAll('.sub,.row-meta')].find(el=>el.textContent?.includes('Signed in as '));if(signed){const text=signed.textContent||'';const email=text.split('Signed in as ')[1]?.trim()||'';if(email){document.getElementById('dashboard-email').textContent=email;document.getElementById('dashboard-avatar').textContent=(email[0]||'C').toUpperCase()}}const stack=document.querySelector('.page-body>.stack');if(stack&&(path==='/dashboard/devices'||path==='/dashboard/workspaces')){const rows=[...stack.querySelectorAll(':scope>.row')];rows.forEach((row,i)=>{const t=(row.querySelector('.row-title')?.textContent||'').trim();const m=(row.querySelector('.row-meta')?.textContent||'').trim();const isWorkspace=/ · (active|sleeping|device_offline)$/.test(t);const isMeta=t.startsWith('Your referral code')||t==='Estimated MCP token usage'||t.startsWith('Last 24 hours')||t.startsWith('Last 30 days')||t.startsWith('All time')||t==='Gateway';if(path==='/dashboard/workspaces'&&!isWorkspace)row.remove();if(path==='/dashboard/devices'&&(isWorkspace||isMeta))row.remove()});const wrap=document.createElement('div');wrap.className='card';const head=document.createElement('div');head.className='section-head';head.innerHTML=path==='/dashboard/workspaces'?'<div><div class="title">Authorized folders</div><div class="label">Only folders explicitly granted from your machines appear here.</div></div>':'<div><div class="title">Paired machines</div><div class="label">Machine runtimes connected to your CodeLocal account.</div></div>';stack.parentNode.insertBefore(wrap,stack);wrap.appendChild(head);const div=document.createElement('div');div.className='divider';wrap.appendChild(div);wrap.appendChild(stack)} })();</script>`
	return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark">` + brandHead + `<title>` + Escape(title) + ` · CodeLocal</title><style>` + styles + `</style></head><body><div class="shell"><div class="sidebar-column"><aside class="sidebar">` + brand + nav + status + `</aside></div><main class="main"><header class="top"><div class="top-copy"><div class="eyebrow"><span class="status-dot green"></span>CodeLocal Cloud</div><div class="h1" id="dashboard-title">` + Escape(title) + `</div><div class="sub">` + Escape(subtitle) + `</div></div></header><div class="page-body">` + body + `</div></main></div>` + script + `</body></html>`
}

func landingPage(subtitle, body string) string {
	return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark">` + brandHead + `<meta name="description" content="Connect ChatGPT securely to project folders you explicitly authorize on your computer."><title>CodeLocal · Connect ChatGPT to your local code</title><style>` + styles + landingStyles + `</style></head><body><div class="landing"><nav class="landing-nav"><div class="landing-nav-inner"><a class="landing-brand" href="/"><img class="landing-logo" src="/assets/codelocal-icon.png" alt="CodeLocal"><span>CodeLocal</span></a><div class="landing-links"><a class="btn ghost" href="#setup">Setup guide</a><a class="btn primary" href="/dashboard">Open dashboard</a></div></div></nav><main class="landing-main"><section class="landing-hero"><div><div class="landing-kicker"><span class="status-dot green"></span>CodeLocal Cloud</div><h1>Connect ChatGPT to the code on your machine.</h1><div class="landing-hero-copy">` + Escape(subtitle) + ` CodeLocal keeps source code, secrets and terminal access local while ChatGPT works through a secure, permission-aware bridge.</div><div class="landing-actions"><a class="btn primary" href="#setup">Set up CodeLocal</a><a class="btn" href="/register">Create account</a></div><div class="privacy-note">Your files stay on your machine. Risky actions still require confirmation.</div></div><div class="connection-preview"><div class="preview-head"><img class="preview-icon" src="/assets/chatgpt-plugin-icon.png" alt="CodeLocal plugin icon"><div><div class="preview-title">CodeLocal</div><div class="preview-sub">Remote MCP for ChatGPT</div></div></div><div class="preview-row"><span>Authentication</span><strong>OAuth</strong></div><div class="preview-row"><span>Runtime</span><strong>Local Go client</strong></div><div class="preview-row"><span>Status</span><span class="badge green">Ready to connect</span></div></div></section><section class="setup-section" id="setup"><div class="section-kicker">Detailed setup</div><h2 class="landing-section-title">ChatGPT is the brain. CodeLocal gives it hands.</h2><div class="section-copy">Grant only the project folders you choose. One lightweight machine runtime can serve multiple authorized projects.</div><div class="setup-layout"><div class="setup-list"><article class="setup-step"><div class="step-title">Install and connect</div><div class="step-summary">Use the same workflow shown in the completed Node landing page. The Go server keeps the same cloud and OAuth architecture.</div><div style="height:16px"></div>` + body + `</article></div><aside class="plugin-panel"><div class="plugin-panel-head"><img class="plugin-panel-icon" src="/assets/chatgpt-plugin-icon.png" alt=""><div><div class="plugin-panel-title">ChatGPT plugin icon</div><div class="plugin-panel-sub">Same production asset as main</div></div></div><div style="height:18px"></div><a class="btn primary" style="width:100%" href="/assets/chatgpt-plugin-icon.png" download="codelocal-chatgpt-plugin-icon.png">Download plugin icon</a><div style="height:12px"></div><div class="label">Source code and secrets remain on the local machine. CodeLocal Cloud coordinates identity, routing and permissions.</div></aside></div></section><footer class="landing-footer"><span>© CodeLocal</span><span>Local source code and secrets remain on your computer.</span></footer></main></div></body></html>`
}

func Page(title, subtitle, body string) string {
	if strings.Contains(title, "CodeLocal Cloud") || strings.HasPrefix(title, "Admin ·") {
		return dashboardPage(title, subtitle, body)
	}
	if title == "CodeLocal" {
		return landingPage(subtitle, body)
	}
	return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light"><meta name="theme-color" content="#f4f7ff">` + brandHead + `<title>` + Escape(title) + ` · CodeLocal</title><style>` + styles + authStyles + `</style></head><body class="auth-body"><div class="auth-wrap"><div class="auth"><div class="brand"><img class="logo" src="/assets/codelocal-icon.png" alt=""><span class="brand-name">CodeLocal</span></div><section class="card"><h1>` + Escape(title) + `</h1><p>` + Escape(subtitle) + `</p>` + body + `</section></div></div><script>` + authScript + `</script></body></html>`
}

func Hidden(fields map[string]string) string {
	var out strings.Builder
	for key, value := range fields {
		out.WriteString(`<input type="hidden" name="` + Escape(key) + `" value="` + Escape(value) + `">`)
	}
	return out.String()
}
